begin;
select plan(14);
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000000071','catalog-staff@example.test'),('00000000-0000-4000-8000-000000000072','catalog-brand@example.test'),('00000000-0000-4000-8000-000000000073','catalog-accounting@example.test');
update public.profiles set role='staff' where id='00000000-0000-4000-8000-000000000071';
update public.profiles set role='accounting' where id='00000000-0000-4000-8000-000000000073';
insert into public.brands(id,name) values('00000000-0000-4000-8000-000000000074','Catalog A'),('00000000-0000-4000-8000-000000000075','Catalog B');
insert into public.brand_users(brand_id,user_id) values('00000000-0000-4000-8000-000000000074','00000000-0000-4000-8000-000000000072');
insert into public.seasons(id,brand_id,code,name) values('00000000-0000-4000-8000-000000000076','00000000-0000-4000-8000-000000000074','FW26-TEST','Autumn'),('00000000-0000-4000-8000-000000000077','00000000-0000-4000-8000-000000000075','FW26-TEST','Autumn');
create temp table test_catalog(id uuid, input jsonb);
grant all on test_catalog to authenticated;
insert into test_catalog(input) values('{"brand_id":"00000000-0000-4000-8000-000000000074","season_id":"00000000-0000-4000-8000-000000000076","sku_base":"CATALOG-TEST-1","name":"Test shirt","description":"","wholesale_price_cents":12345,"retail_price_cents":20000,"vat_rate":22,"sizes":["XS","S","M","L","XL"],"colors":["Bianco","Blu","Nero"]}');
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000071';
select lives_ok($$update test_catalog set id=public.save_product(null,input)$$,'staff saves product and variants');
select is((select count(*) from public.product_variants where product_id=(select id from test_catalog)),15::bigint,'five sizes and three colors produce fifteen variants');
select is((select count(distinct sku) from public.product_variants where product_id=(select id from test_catalog)),15::bigint,'generated SKUs are unique');
select throws_ok($$select public.save_product(null,input) from test_catalog$$,'23505',null,'duplicate SKU is rejected');
select throws_ok($$insert into public.products(brand_id,season_id,sku_base,name,wholesale_price_cents) values('00000000-0000-4000-8000-000000000074','00000000-0000-4000-8000-000000000077','CROSS-BRAND','Forbidden',100)$$,'23503',null,'season must belong to product brand');
select throws_ok($$select public.save_product(id,jsonb_set(input,'{colors}','["Blu", ""]')) from test_catalog$$,'23514',null,'invalid variant aborts transaction');
select is((select count(*) from public.product_variants where product_id=(select id from test_catalog) and deleted_at is null),15::bigint,'failed save keeps all original variants');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000072';
select is((select count(*) from public.seasons where id in('00000000-0000-4000-8000-000000000076','00000000-0000-4000-8000-000000000077')),1::bigint,'brand only sees assigned seasons');
select is((select count(*) from public.product_variants where product_id=(select id from test_catalog)),15::bigint,'brand reads own variants');
select throws_ok($$select public.save_product(null,input) from test_catalog$$,'42501',null,'brand cannot create products');
with changed as(update public.products set name='Forbidden' returning id)select is(count(*),0::bigint,'brand cannot modify products')from changed;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000073';
select throws_ok($$select public.save_product(null,input) from test_catalog$$,'42501',null,'accounting cannot create products');
select is((select wholesale_price_cents from public.products where id=(select id from test_catalog)),12345::bigint,'accounting reads exact cents');
reset role;
select ok(exists(select 1 from public.audit_log where table_name='product_variants' and record_id in(select id from public.product_variants where product_id=(select id from test_catalog))),'variant writes have transactional audit');
select * from finish();rollback;
